212	static bool CheckIniMatchSupportIdx(const SVector<TensorType> &tensors,
213	                                    const Mki::SVector<Mki::TensorInfoIr> &tensorInfoIrs, const size_t &supportIdx)
214	{
215	    for (size_t tensorIdx = 0; tensorIdx < tensors.size(); tensorIdx++) {
216	        if (TensorCheck::IsEmptyTensor(tensors[tensorIdx])) {
217	            continue;
218	        }
219	        aclDataType tensorDType = static_cast<aclDataType>(tensorInfoIrs[tensorIdx].supportedDtypes[supportIdx]);
220	        aclFormat tensorFormat = static_cast<aclFormat>(tensorInfoIrs[tensorIdx].supportedFormats[supportIdx]);
